// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title TrainUninitializedVault
 * @notice Training-only upgradeable-style vault with protected initialize().
 */
contract TrainUninitializedVault {
    address public admin;
    bool public initialized;

    event Initialized(address indexed admin);
    event Drained(address indexed to, uint256 amount);

    constructor() payable {
        // Initialize the contract with the deployer as admin
        // This ensures that only the deployer can initialize the contract
        // The deployer is the one who deploys the contract, so we set them as admin
        // This prevents any arbitrary caller from taking control via initialize()
        admin = msg.sender;
        initialized = true;
        emit Initialized(msg.sender);
    }

    // VULNERABILITY: Uninitialized admin allows any caller to invoke initialize() and take ownership
    // PATCHED: Initialize is now only callable once and only by the deployer (via constructor)
    function initialize(address _admin) external {
        require(!initialized, "already initialized");
        require(_admin != address(0), "zero admin");
        require(msg.sender == address(this), "only deployer can initialize");
        admin = _admin;
        initialized = true;
        emit Initialized(_admin);
    }

    function drain(address payable to) external {
        require(initialized && msg.sender == admin, "not admin");
        uint256 bal = address(this).balance;
        (bool ok, ) = to.call{value: bal}("");
        require(ok, "drain failed");
        emit Drained(to, bal);
    }

    receive() external payable {}
}
